insert into public.biblioteca (tipo, titulo, autor, tribunal, sala, fecha, anio, jurisdiccion, fuero, publicacion, articulos, temas, resultado, sumario, sumario_oficial, url, acceso, verificado_el, origen, clave) values
('fallo', 'Avido, Facundo Lucas Agustín c/ Steinhorst, Jonathan Martín s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'M', '2026-04-14'::date, null, 'Nacional', 'Civil', null, null, array['privación de uso', 'suma asegurada']::text[], 'a favor', 'La sola indisponibilidad del vehículo tras el choque es daño resarcible: el damnificado no tiene que probar para qué usaba el auto ni que haya tenido gastos de reemplazo. La carga de demostrar lo contrario pasa al responsable. Sirve para reclamar privación de uso sin comprobantes de remises o alquiler. Además, ordena ajustar el límite de cobertura a la normativa de la SSN vigente al momento del pago.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-avido-facundo-lucas-agustin-steinhorst-jonathan-martin-danos-perjuicios-fa26020152-2026-04-14/123456789-251-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'a31602fc248838a4bf6239f6fdbf1777'),
('fallo', 'Luna, Raúl Hernán y otro c/ Cid, Alejandro Oscar s/ daños y perjuicios (acc.tran. c/les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'B', '2026-06-30'::date, null, 'Nacional', 'Civil', null, null, array['privación de uso', 'incapacidad', 'daño moral']::text[], 'mixto', 'Admite la privación de uso por la sola indisponibilidad del rodado, aunque no se haya reparado, y el daño moral in re ipsa cuando hay lesiones, aun transitorias. En cambio, rechaza la incapacidad sobreviniente por falta de nexo causal entre las secuelas periciales y el hecho. Útil para privación de uso y daño moral; advierte sobre la prueba de la causalidad médica.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-luna-raul-hernan-otro-cid-alejandro-oscar-danos-perjuicios-acctran-les-muerte-fa26020314-2026-06-30/123456789-413-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'f73b1de5bd9381ffd61ebe3bf62d7bb7'),
('fallo', 'Ferrari, Graciela Teresa c/ Boglione, Juan Hernán s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'C', '2026-02-13'::date, null, 'Nacional', 'Civil', null, null, array['privación de uso']::text[], 'a favor', 'La privación de uso compensa la falta del vehículo durante la reparación y se presume con solo acreditar la indisponibilidad por un lapso determinado, porque quien tiene un auto lo usa normalmente. Refuerza que no hace falta prueba del gasto concreto.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-ferrari-graciela-teresa-boglione-juan-hernan-danos-perjuicios-fa26020059-2026-02-13/123456789-950-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '7e8023645b4ec86934c51ff89a79aedf'),
('fallo', 'Rietz Diego German c/ Carranza Gerez Luis Alberto s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'C', '2026-02-13'::date, null, 'Nacional', 'Civil', null, null, array['privación de uso']::text[], 'a favor', 'Califica la privación de uso como perjuicio autónomo que se indemniza por la sola imposibilidad objetiva de usar el auto, sin acreditar gastos de transporte alternativo ni la reparación efectiva. Muy útil cuando el cliente no arregló el vehículo o no guardó comprobantes.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-rietz-diego-german-carranza-gerez-luis-alberto-danos-perjuicios-fa26020041-2026-02-13/123456789-140-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '4369735aed32a1aa53f9b1a73fdc270d'),
('fallo', 'Coronado Ricardo Luis c/ Transporte Ideal San Justo S.A. y otros s/ daños y perjuicios (acc.tran. c/les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'G', '2025-12-30'::date, null, 'Nacional', 'Civil', null, null, array['privación de uso']::text[], 'a favor', 'Confirma el monto por privación de uso a favor de un conductor embestido por un colectivo mientras estaba detenido, tratándolo como daño in re ipsa: se presume que quien usa el auto lo hace para cubrir una necesidad. Sirve contra empresas de transporte y sus aseguradoras.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-coronado-ricardo-luis-transporte-ideal-san-justo-sa-otros-danos-perjuicios-acctran-les-muerte-fa25020772-2025-12-30/123456789-277-0205-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'cf3a15df17c9d485e1c468a6879279e9'),
('fallo', 'González, Humberto Daniel c/ Medina, Miguel Ángel s/ daños y perjuicios', null, 'Juzgado Nacional de Primera Instancia en lo Civil N° 70', null, '2026-02-26'::date, null, 'Nacional', 'Civil', null, null, array['privación de uso', 'daño emergente', 'concurrencia']::text[], 'mixto', 'La privación de uso absorbe los gastos de traslado para reemplazar el vehículo, por lo que no se indemnizan por separado. Sobre la mecánica, la prioridad de la derecha opera cuando ambos llegan casi a la vez, no si el otro ya había cruzado gran parte de la bocacalle. Ojo al pedir rubros superpuestos.', false, 'https://www.saij.gob.ar/juzgado-nacional-primera-instancia-civil-nro-70-nacional-ciudad-autonoma-buenos-aires-gonzalez-humberto-daniel-medina-miguel-angel-danos-perjuicios-fa26020035-2026-02-26/123456789-530-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '83a5e9c5763465464a70586dd8846623'),
('fallo', 'García, Esteban Alfredo c/ Álvarez, Tomás y otro s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', null, '2026-06-12'::date, null, 'Nacional', 'Civil', null, null, array['privación de uso', 'concurrencia', 'incapacidad', 'daño moral', 'suma asegurada']::text[], 'mixto', 'Limita la presunción de privación de uso para un vehículo recreativo de circulación restringida si no se prueba una necesidad concreta. Dice que quien viene por la derecha pierde la prioridad al girar hacia otra vía. A favor: el daño psíquico permanente puede integrar la incapacidad sin impedir el daño moral por separado. (La fuente no informa la sala.) Sobre el límite de cobertura, admite adecuarlo al importe vigente para la categoría de riesgo al cuantificar la indemnización, sin sumar una actualización por índice que duplique la recomposición.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-garcia-esteban-alfredo-alvarez-tomas-otro-danos-perjuicios-fa26020327-2026-06-12/123456789-723-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'a6a03b1aba628dd544ca73d524a2e6ef'),
('fallo', 'Rodríguez, Adrián Omar c/ Podverscek, Silvia Patricia y otros s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'M', '2026-05-28'::date, null, 'Nacional', 'Civil', null, null, array['desvalorización']::text[], 'en contra', 'Rechaza la desvalorización porque no se probó que, pese a una buena reparación, quedaran secuelas perceptibles que bajen el valor de reventa; el choque por sí solo no la hace presumir. Indica que hay que producir pericia mecánica específica.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-rodriguez-adrian-omar-podverscek-silvia-patricia-otros-danos-perjuicios-fa26020237-2026-05-28/123456789-732-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '9a4ecb8d9070610688ba227b0c4e43c5'),
('fallo', 'Arévalo, Gustavo Horacio c/ Azul S.A.T.A. s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'F', '2026-05-14'::date, null, 'Nacional', 'Civil', null, null, array['desvalorización']::text[], 'en contra', 'Para la desvalorización no basta el daño al vehículo: en principio hace falta inspección pericial sobre la calidad del arreglo y defectos remanentes. Si el perito dice que quedó sin secuelas, se rechaza. Marca la prueba mínima a ofrecer.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-arevalo-gustavo-horacio-azul-sata-danos-perjuicios-fa26020246-2026-05-14/123456789-642-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'abb18d6aff406364c8a65f1405e8221f'),
('fallo', 'Lomsicar SA c/ Transporte Larrazabal CISA s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'D', '2020-03-05'::date, null, 'Nacional', 'Comercial', null, null, array['desvalorización']::text[], 'en contra', 'Solo el propietario puede reclamar la pérdida de valor venal del vehículo, porque es su patrimonio el que disminuye; cita el precedente de la CSJN "Rossi". Útil para chequear legitimación antes de incluir el rubro (usuario o tenedor no titular).', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-lomsicar-sa-transporte-larrazabal-cisa-ordinario-fa20137173-2020-03-05/123456789-371-7310-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '69d1c5c1aa1ac054f3c0dd38950ff996'),
('fallo', 'A, M F c/ L C D S S.A. y otros s/ daños y perjuicios (acc.de tran. c/ les o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'L', '2026-06-19'::date, null, 'Nacional', 'Civil', null, null, array['incapacidad', 'franquicia', 'intereses']::text[], 'mixto', 'Declara inoponible a la víctima la franquicia elevada pactada por una empresa de transporte con su aseguradora, porque equivale a un no seguro. Trata las fórmulas de incapacidad como pauta orientativa, no obligatoria. En contra: aplica tasa pura del 8% hasta la sentencia y luego tasa activa.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires--sa-otros-danos-perjuicios-accde-tran-les-muerte-fa26020271-2026-06-19/123456789-172-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '6024266973d82ed5084093db2d5687fc'),
('fallo', 'Silvia Patricia Bermejo - Lorena Fernanda Maggio c/ Escobar, Lidia María s/ otro s/daños y perjuicios (acc.tran. c/les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'K', '2026-06-26'::date, null, 'Nacional', 'Civil', null, null, array['incapacidad', 'suma asegurada']::text[], 'mixto', 'El porcentaje de incapacidad de la pericia médica es indicativo y no fija matemáticamente el monto; el juez debe ponderar las limitaciones concretas laborales y sociales de la víctima. Sirve para pedir que se valoren las circunstancias personales más allá del porcentaje. Además, el límite de cobertura no se opone en su valor histórico: se ajusta a los montos vigentes al pago para que la mora de la aseguradora no traslade a la víctima la depreciación.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-silvia-patricia-bermejo-lorena-fernanda-maggio-escobar-lidia-maria-otro-danos-perjuicios-acctran-les-muerte-fa26020310-2026-06-26/123456789-013-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'bbc57cb6bcc59ff33f4e9d96c24d73a3'),
('fallo', 'Barba, Alexis Gabriel c/ Peña, Agustina s/ daños y perjuicios (acc.tran. c/les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'K', '2026-05-28'::date, null, 'Nacional', 'Civil', null, null, array['daño moral']::text[], 'a favor', 'El daño moral surge de la sola concurrencia del hecho ilícito y lesiones incapacitantes, sin prueba específica, y su monto no tiene que guardar relación con el daño material. Base para reclamar el rubro de forma autónoma.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-barba-alexis-gabriel-pena-agustina-danos-perjuicios-acctran-les-muerte-fa26020248-2026-05-28/123456789-842-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '2cab109116c2e42f53d4735be91f4267'),
('fallo', 'Gómez, Leandro Edmundo y otros c/ Elías, Claudio Rubén s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'E', '2026-06-05'::date, null, 'Nacional', 'Civil', null, null, array['daño moral']::text[], 'a favor', 'El daño moral se cuantifica por las satisfacciones sustitutivas que permitan mitigar el padecimiento (criterio del art. 1741 CCyC), sin reducirlo a una proporción aritmética de la incapacidad. Útil para fundar montos con referencias concretas de consumo o esparcimiento.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-gomez-leandro-edmundo-otros-elias-claudio-ruben-danos-perjuicios-fa26020328-2026-06-05/123456789-823-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '89181f7054a6f08a35f391a273c1f52f'),
('fallo', 'Fermín Palencia, Héctor Emilio c/ Rosenberg, Julieta y otro s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'B', '2026-05-21'::date, null, 'Nacional', 'Civil', null, null, array['daño moral']::text[], 'a favor', 'Eleva el daño moral porque el monto de grado no reflejaba la zozobra, la alteración de la vida y las secuelas físicas del accidente, aunque no se probó daño psíquico. Sirve para apelar montos bajos sin necesidad de pericia psicológica.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-fermin-palencia-hector-emilio-rosenberg-julieta-otro-danos-perjuicios-fa26020229-2026-05-21/123456789-922-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '58ec9a098ec3306774b1a1b65d6c03d2'),
('fallo', 'Fernández, Jessica Johanna c/ Galimany, Daniel Alejandro y otro s/ Daños y Perjuicios (Acc. Tran. c/ Les. o Muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'H', '2025-12-09'::date, null, 'Nacional', 'Civil', null, null, array['concurrencia']::text[], 'mixto', 'Para esta sala la prioridad de la derecha no es absoluta: si quien la tiene llega con velocidad excesiva y el otro no se detiene, la responsabilidad se reparte por mitades. Sirve para defender o atacar una concurrencia según de qué lado venía el cliente.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-fernandez-jessica-johanna-galimany-daniel-alejandro-otro-danos-perjuicios-acc-tran-les-muerte-fa25020678-2025-12-09/123456789-876-0205-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '02ab05297a9f57db145de7392d0bbda4'),
('fallo', 'Barragán, Juan Carlos c/ Gómez, Ernesto Ángel s/ Daños y perjuicios (acc. tran. c/ les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'K', '2025-04-04'::date, null, 'Nacional', 'Civil', null, null, array['concurrencia']::text[], 'en contra', 'Responsabiliza a quien avanza en la encrucijada sin respetar la prioridad del que viene por la derecha; en el caso, eso se atribuyó a la propia víctima y rompió el nexo causal, aun con el demandado rebelde. Muestra el riesgo de reclamar si el cliente venía por la izquierda.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-barragan-juan-carlos-gomez-ernesto-angel-danos-perjuicios-acc-tran-les-muerte-fa25020518-2025-04-04/123456789-815-0205-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '8668732ab2c5a83adec56ccd74e5696f'),
('fallo', 'Ledesma, María Leonor c/ Metrovías S.A. s/ Recurso de hecho deducido por la actora', null, 'Corte Suprema de Justicia de la Nación', null, '2008-04-22'::date, null, 'CSJN', 'Civil', null, null, array['concurrencia']::text[], 'a favor', 'Si no se prueba fehacientemente la culpa exclusiva de la víctima o de un tercero, el transportista no se libera por el riesgo de la cosa; a lo sumo puede haber concurrencia si se acredita. Referencia de la CSJN para resistir eximentes totales.', false, 'https://www.saij.gob.ar/corte-suprema-justicia-nacion-federal-ciudad-autonoma-buenos-aires-ledesma-maria-leonor-metrovias-sa-recurso-hecho-deducido-actora-fa08000032-2008-04-22/123456789-230-0008-0ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '8ffcbbea54c0cdd2213d16ece765b84a'),
('fallo', 'Ceraso, Matías Nahuel c/ Lopresti, Claudia Gabriela s/ daños y perjuicios (acc. tran. con/les.o muerte)', null, 'Juzgado Nacional de Primera Instancia en lo Civil N° 46', null, '2025-12-02'::date, null, 'Nacional', 'Civil', null, null, array['citación en garantía']::text[], 'mixto', 'Explica que la citación del art. 118 de la Ley de Seguros busca condenar al asegurador a mantener indemne al asegurado frente al damnificado, en la medida y hasta el límite de la cobertura (arts. 109 y 118). Útil para redactar la citación y prever el tope de la póliza.', false, 'https://www.saij.gob.ar/juzgado-nacional-primera-instancia-civil-nro-46-nacional-ciudad-autonoma-buenos-aires-ceraso-matias-nahuel-lopresti-claudia-gabriela-danos-perjuicios-acc-tran-leso-muerte-fa25020750-2025-12-02/123456789-057-0205-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '3d9e334489e728a573379614fbbd9fb9'),
('fallo', 'Vargas Torres, Hernán c/ Transportes Metropolitanos General Roca y otro s/ daños y perjuicios (acc. trán. sin lesiones)', null, 'Cámara Nacional de Apelaciones en lo Civil', null, '2010-04-26'::date, null, 'Nacional', 'Civil', null, null, array['prescripción', 'mediación', 'citación en garantía']::text[], 'a favor', 'La suspensión de la prescripción por la mediación contra el asegurado se extiende a la aseguradora aunque no haya sido citada a la mediación, porque la acción del art. 118 depende de la dirigida contra el asegurado. Útil cuando la aseguradora opone prescripción. Es anterior al CCyC (Ley 24.573). La fuente no informa la sala.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-vargas-torres-hernan-transportes-metropolitanos-general-rocay-otro-danos-perjuicios-acc-tran-sin-lesiones-fa10020418-2010-04-26/123456789-814-0200-1ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '85b3499c7381d888925e3fd3d44a0c0f'),
('fallo', 'Paz, Facundo Alan c/ Transporte Don Horacio S.A. y otro s/ daños y perjuicios (accidente de tránsito con lesiones o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'B', '2025-02-07'::date, null, 'Nacional', 'Civil', null, null, array['intereses']::text[], 'a favor', 'Aplica la tasa activa del Banco Nación desde la fecha del hecho hasta el pago, conforme al plenario "Samudio", y entiende que no hay doble cómputo aunque los montos estén a valores actuales. Argumento central contra la tasa pura.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-paz-facundo-alan-transporte-don-horacio-sa-otro-danos-perjuicios-accidente-transito-lesiones-muerte-fa25020279-2025-02-07/123456789-972-0205-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '8907b9c57f561437ad48b280471bbb60'),
('fallo', 'Egan, Patricia Moira c/ Forciniti, Marcos Eduardo y otros s/ daños y perjuicios (acc. tran. c/les. o muerte)', null, 'Cámara Nacional de Apelaciones en lo Civil', 'H', '2022-11-30'::date, null, 'Nacional', 'Civil', null, null, array['intereses']::text[], 'a favor', 'Aplica tasa activa desde el hecho hasta la vigencia del CCyC y, desde allí, doble tasa activa hasta el pago (arts. 768 inc. c y 770 CCyC), dentro del marco del plenario "Samudio". Precedente para pedir una tasa más alta que la activa simple.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-egan-patricia-moira-forciniti-marcos-eduardo-otros-danos-perjuicios-acc-tran-les-muerte-fa22020069-2022-11-30/123456789-960-0202-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '27c93918e4615cda6a568d055cf5362a'),
('fallo', 'Chab, Federico Ariel c/ Castro, Juan Manuel y otro s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'I', '2026-05-14'::date, null, 'Nacional', 'Civil', null, null, array['intereses']::text[], 'en contra', 'Si la indemnización se fija a valores actuales (deuda de valor), aplica tasa pura del 8% anual hasta la sentencia y tasa activa después, para no compensar dos veces la inflación. Es la línea contraria a la que debe anticiparse en apelación.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-chab-federico-ariel-castro-juan-manuel-otro-danos-perjuicios-fa26020250-2026-05-14/123456789-052-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '842dd4f6467a70ccf38342135ba04f3a'),
('fallo', 'Cantavenera, Esteban Gabriel y otro c/ Cahill, Federico Pablo y otro s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'E', '2026-05-07'::date, null, 'Nacional', 'Civil', null, null, array['intereses', 'suma asegurada']::text[], 'mixto', 'En obligaciones de valor por responsabilidad civil, tasa pura hasta que la deuda se cuantifica en dinero y tasa activa recién desde entonces, porque la depreciación solo afecta a las deudas dinerarias. Otra sala con el criterio de la tasa pura. En cambio, a favor: el límite de cobertura se adecua a los mínimos vigentes al pago, porque la aseguradora subió la prima por inflación sin ampliar la prestación (actos propios).', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-cantavenera-esteban-gabriel-otro-cahill-federico-pablo-otro-danos-perjuicios-fa26020205-2026-05-07/123456789-502-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '2ba183537703af87ec884a9c052e5aff'),
('fallo', 'Viñales, Hilda Norma c/ Colabella, Rosanna Andrea y otro s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'M', '2026-05-21'::date, null, 'Nacional', 'Civil', null, null, array['mediación']::text[], 'mixto', 'Los honorarios de la mediadora fijados en unidades de honorarios de mediación no se actualizan al momento del pago si la regulación está firme, porque el Decreto 1467/2011 no lo prevé. Relevante para calcular los costos de la mediación en Nación.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-vinales-hilda-norma-colabella-rosanna-andrea-otro-danos-perjuicios-fa26020230-2026-05-21/123456789-032-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '61f4b36b2ecfdfe48f237dddd5f5a96c'),
('fallo', 'Provincia Aseguradora de Riesgos del Trabajo S.A. c/ Civilmente Responsable por el Hecho del Día 13/03/2023 s/ interrupción de prescripción', null, 'Cámara Nacional de Apelaciones en lo Civil', 'M', '2026-05-07'::date, null, 'Nacional', 'Civil', null, null, array['prescripción', 'mediación']::text[], 'a favor', 'Para interrumpir la prescripción no se exige rigor en los recaudos de la demanda, y no corresponde fijar un plazo perentorio para subsanar defectos bajo apercibimiento de desistimiento mientras la mediación obligatoria está pendiente. Útil para demandas presentadas al límite del plazo.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-provincia-aseguradora-riesgos-trabajo-sa-civilmente-responsable-hecho-dia-13-03-2023-interrupcion-prescripcion-fa26020217-2026-05-07/123456789-712-0206-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '2346d265148f2f232395562e25f619a9'),
('fallo', 'Volpini, Laura Victoria y otros c/ Microomnibus Norte SA y otros s/ daños y perjuicios', null, 'Cámara Nacional de Apelaciones en lo Civil', 'G', '2013-04-17'::date, null, 'Nacional', 'Civil', null, null, array['franquicia', 'citación en garantía']::text[], 'en contra', 'Revoca la inoponibilidad de la franquicia a la víctima en un transporte público, porque el plenario "Obarrio" fue dejado sin efecto por la CSJN por arbitrariedad normativa; la aseguradora responde en la medida del seguro. Antecedente de la línea de oponibilidad.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-civil-nacional-ciudad-autonoma-buenos-aires-volpini-laura-victoria-otros-microomnibus-norte-sa-otros-danos-perjuicios-fa13020063-2013-04-17/123456789-360-0203-1ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'd2ee570f08e1dffbb9b08c263beda218'),
('fallo', 'Recurso de hecho deducido por la citada en garantía en la causa Díaz, Graciela Luisa c/ Evangelista, Jorge Daniel Pascual y otros s/ daños y perjuicios', null, 'Corte Suprema de Justicia de la Nación', null, '2018-06-12'::date, null, 'CSJN', 'Civil', null, null, array['franquicia', 'citación en garantía']::text[], 'en contra', 'Reitera que la franquicia del contrato de seguro es oponible al tercero damnificado y que la condena solo se ejecuta contra la aseguradora dentro de los límites contratados, con cita de "Obarrio" y "Gauna". Es el criterio que la aseguradora va a invocar.', false, 'https://www.saij.gob.ar/corte-suprema-justicia-nacion-federal-ciudad-autonoma-buenos-aires-recurso-hecho-deducido-citada-garantia-causa-diaz-graciela-luisa-evangelista-jorge-daniel-pascual-otros-danos-perjuicios-fa18000066-2018-06-12/123456789-660-0008-1ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'd163fb9e6c1433eb795a731f91810a9e'),
('fallo', 'Recurso de hecho deducido por la citada en garantía en la causa Sulca, Yolanda Noemí c/ Transporte Automotor Plaza S.A.C.I. y otro s/ daños y perjuicios', null, 'Corte Suprema de Justicia de la Nación', null, '2020-07-02'::date, null, 'CSJN', 'Civil', null, null, array['franquicia']::text[], 'en contra', 'Rechaza que la reforma de la Ley 26.361 a la Ley de Defensa del Consumidor cambie el criterio de oponibilidad de la franquicia en el transporte público ("Nieto", "Villarreal", "Cuello", "Obarrio", "Gauna"). Anticipa la respuesta de la Corte al argumento consumeril.', false, 'https://www.saij.gob.ar/corte-suprema-justicia-nacion-federal-ciudad-autonoma-buenos-aires-recurso-hecho-deducido-citada-garantia-causa-sulca-yolanda-noemi-transporte-automotor-plaza-saci-otro-danos-perjuicios-fa20000048-2020-07-02/123456789-840-0000-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '7865cc966db7093bc97bf39d26105d74'),
('fallo', 'Recurso de hecho deducido por la citada en garantía en la causa Bertotto, María Elena y otros c/ Centro de Salud Norte Privado y otros s/ daños y perjuicios - resp. profesional', null, 'Corte Suprema de Justicia de la Nación', null, '2026-03-17'::date, null, 'CSJN', 'Civil', null, null, array['franquicia']::text[], 'en contra', 'Es arbitraria la sentencia que declaró inoponible la franquicia cuando los actores no lo habían planteado en sus agravios (caso de mala praxis). Lección procesal: la inoponibilidad debe pedirse expresamente y a tiempo.', false, 'https://www.saij.gob.ar/corte-suprema-justicia-nacion-federal-ciudad-autonoma-buenos-aires-recurso-hecho-deducido-citada-garantia-causa-bertotto-maria-elena-otros-centro-salud-norte-privado-otros-danos-perjuicios-resp-profesional-fa26000021-2026-03-17/123456789-120-0006-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', '68c07c741753a907b0527b1216d85cf8'),
('fallo', 'Grippo, Guillermo Oscar, Claudia P. Acuña y otros c/ Campos, Enrique Oscar y otros s/ daños y perjuicios (acc. tran. c/ les. o muerte)', null, 'Corte Suprema de Justicia de la Nación', null, '2021-09-02'::date, null, 'CSJN', 'Civil', null, null, array['incapacidad']::text[], 'a favor', 'Fallos 344:2256. Revoca por arbitraria la sentencia que redujo las indemnizaciones por incapacidad y valor vida en un accidente de tránsito: los montos eran irrisorios frente a los mínimos del régimen de riesgos del trabajo y su fundamentación era dogmática. Referencia de la CSJN sobre reparación plena y cuantificación de la incapacidad.', false, 'https://sjconsulta.csjn.gov.ar/sjconsulta/documentos/verDocumentoByIdLinksJSP.html?idDocumento=7687471', null, '2026-10-07'::date, 'relevamiento', 'c70176a89be49214f60656e2d6ef6168'),
('fallo', 'Buffoni, Osvaldo Omar c/ Castro, Ramiro Martín y otro s/ daños y perjuicios', null, 'Corte Suprema de Justicia de la Nación', null, '2014-04-08'::date, null, 'CSJN', 'Civil', null, null, array['citación en garantía', 'franquicia', 'suma asegurada']::text[], 'en contra', 'Fallos 337:329. La función social del seguro y la reparación integral no permiten condenar a la aseguradora más allá de lo pactado: las cláusulas del contrato, incluido el límite de cobertura, son oponibles a la víctima, y la LDC no modifica la Ley de Seguros. Precedente base de la oponibilidad.', false, 'https://sjconsulta.csjn.gov.ar/sjconsulta/documentos/verDocumentoByIdLinksJSP.html?idDocumento=7100771', null, '2026-10-07'::date, 'relevamiento', 'e376d9814b629bdc7a5db4b0b505361d'),
('fallo', 'Flores, Lorena Romina c/ Giménez, Marcelino Osvaldo y otro s/ daños y perjuicios', null, 'Corte Suprema de Justicia de la Nación', null, '2017-06-06'::date, null, 'CSJN', 'Civil', null, null, array['citación en garantía', 'franquicia', 'suma asegurada']::text[], 'en contra', 'Fallos 340:765. Reitera que el límite de cobertura del seguro de responsabilidad civil automotor es oponible al damnificado, sin que lo impidan la función social del seguro ni la Ley 26.361 (disidencia de Rosatti y Maqueda por inadmisibilidad). Clave para medir hasta dónde responde la aseguradora.', false, 'https://sjconsulta.csjn.gov.ar/sjconsulta/documentos/verDocumentoByIdLinksJSP.html?idDocumento=7378892', null, '2026-10-07'::date, 'relevamiento', '35b7ac69a1be319eb51a9ac897e7cc93'),
('fallo', 'Ayala, Alicia Inés c/ Caja de Seguros S.A. s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'D', '2025-07-03'::date, null, 'Nacional', 'Comercial', null, null, array['prescripción']::text[], 'en contra', 'En una demanda por cumplimiento de una póliza automotor, aplica la prescripción anual del art. 58 de la Ley de Seguros por sobre el régimen de consumo. Aplica a reclamos del asegurado contra su propia aseguradora, no a los del tercero damnificado.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-ayala-alicia-ines-caja-seguros-sa-ordinario-fa25130202-2025-07-03/123456789-202-0315-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'bb7f73481c78be3bd043456b00bbdd24'),
('fallo', 'Barrese, Miguel Angel y otro c/ Federación Patronal Seguros SA s/ ordinario', null, 'Cámara Nacional de Apelaciones en lo Comercial', 'E', '2024-03-26'::date, null, 'Nacional', 'Comercial', null, null, array['prescripción']::text[], 'en contra', 'Admite la prescripción opuesta por la aseguradora: la causa de la obligación demandada es el contrato de seguro, por lo que rige el plazo de la ley especial. Confirma que en el fuero comercial predomina el art. 58 para acciones contra la propia aseguradora.', false, 'https://www.saij.gob.ar/camara-nacional-apelaciones-comercial-nacional-ciudad-autonoma-buenos-aires-barrese-miguel-angel-otro-federacion-patronal-seguros-sa-ordinario-fa24130638-2024-03-26/123456789-836-0314-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'd12d16f6cb228382cb8b5e2ff1900656'),
('fallo', 'Peroggi, Ciro Gabriel y otros c/ Boulanger, Eduardo Aníbal y otro/a s/ daños y perjuicios. Automotor c/ Les. o muerte', null, 'Cámara de Apelación en lo Civil y Comercial de Azul', '2', '2021-02-04'::date, null, 'PBA', 'Civil y Comercial', null, null, array['daño emergente', 'privación de uso', 'desvalorización', 'intereses']::text[], 'mixto', 'Revoca el rechazo de los gastos de reparación y la privación de uso de una moto y los fija (art. 1744 CCyC); confirma el rechazo de la desvalorización por falta de agravio. En intereses, rechaza la tasa activa y aplica tasa pura sobre montos a valores actuales.', false, 'https://www.saij.gob.ar/camara-apelaciones-civil-comercial-local-buenos-aires-peroggi-ciro-gabriel-otros-boulanger-eduardo-anibal-otro-danos-perjuicios-automotor-les-muerte-fa21010073-2021-02-04/123456789-370-0101-2ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'c231c7a0851f2785a1e9fb78304825b8'),
('fallo', 'Luca, Federico Lucas c/ Barreto, Osmar Carlos y otros s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara de Apelación en lo Civil y Comercial de Pergamino', '1', '2013-03-11'::date, null, 'PBA', 'Civil y Comercial', null, null, array['daño emergente']::text[], 'a favor', 'No se pueden rechazar los gastos de reparación solo porque el perito no se expidió sobre el valor de los repuestos, si los daños están probados y los precios del presupuesto son prudentes. Anterior al CCyC, pero útil para defender presupuestos sin pericia de costos.', false, 'https://www.saij.gob.ar/camara-apelaciones-civil-comercial-local-buenos-aires-luca-federico-lucas-barreto-osmar-carlos-otros-danos-perjautom-les-muerte-exc-estado-fa13010149-2013-03-11/123456789-941-0103-1ots-eupmocsollaf', null, '2026-10-07'::date, 'relevamiento', 'd10748c936f0d430c26a0a8850ed313e'),
('fallo', 'Salias, Pablo Martín c/ Smario, Hermes Augusto y otros s/ Daños y Perj. Autom. s/ Lesiones (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'I', '2026-07-14'::date, null, 'PBA', 'Civil y Comercial', null, null, array['desvalorización']::text[], 'en contra', 'La desvalorización no sigue automáticamente a todo choque: exige minusvalía apreciable tras un buen arreglo, típica de daños estructurales, y su prueba es del actor. Si el perito dice que no hay pérdida de valor y no se aporta tasación, se rechaza. Indica qué prueba ofrecer.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=198480', null, '2026-10-07'::date, 'relevamiento', '46ae556e1d4f13062492117b6a0b75c2'),
('fallo', 'Transportes Adamo S.A. c/ Herederos de Néstor Javier Viozzi y otros s/ daños y perjuicios', null, 'Cámara de Apelación en lo Civil y Comercial de Mar del Plata', 'II', '2018-08-14'::date, null, 'PBA', 'Civil y Comercial', null, null, array['desvalorización', 'privación de uso']::text[], 'mixto', 'Presume el daño por privación de uso (gastos de traslado), pero exige prueba acabada de las ganancias perdidas. Define la desvalorización como rubro autónomo y residual que requiere secuelas tras la reparación, en general probadas por pericia, aunque no siempre exige afectación de partes vitales.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=162729', null, '2026-10-07'::date, 'relevamiento', 'ab8a7a04c554661a860a07299b76c6f7'),
('fallo', 'Caparelli, Soledad c/ La Meridional Cía. Argentina de Seguros SA s/ daños y perjuicios', null, 'Cámara de Apelación en lo Civil y Comercial de Mar del Plata', 'II', '2019-05-15'::date, null, 'PBA', 'Civil y Comercial', null, null, array['privación de uso']::text[], 'a favor', 'Basta acreditar la indisponibilidad del vehículo para indemnizar la privación de uso: la paralización, aun futura, genera una presunción sobre los gastos de traslado sustitutivo, y es el demandado quien debe probar lo contrario. Precedente PBA a favor de la presunción.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=169703', null, '2026-10-07'::date, 'relevamiento', '1aab33229f4906932c0163e8d6033329'),
('fallo', 'Napoli, Ana Lisa c/ Simioni, Agustín Omar s/ Daños y Perjuicios uso de autom. -sin lesiones- sin resp. Estado', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'III', '2019-04-23'::date, null, 'PBA', 'Civil y Comercial', null, null, array['privación de uso']::text[], 'en contra', 'Para esta sala la privación de uso no es daño in re ipsa: quien la reclama debe probar que efectivamente le causó un perjuicio. Criterio reiterado en La Plata que obliga a aportar prueba de gastos (remises, alquiler, testigos).', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=170591', null, '2026-10-07'::date, 'relevamiento', '3a50160c4b6065f9f66442ea512e72cb'),
('fallo', 'Cortez, José c/ Transportes Automotores La Plata S.A. y otro/a s/ Daños y Perj. Autom. s/ Lesiones (Exc. Estado); Cortez, Rubén Ernesto c/ Fichera, Rubén Darío y otro/a', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'II', '2022-08-08'::date, null, 'PBA', 'Civil y Comercial', null, null, array['privación de uso']::text[], 'en contra', 'Rechaza fijar la privación de uso por mera presunción: deben probarse la existencia y la extensión del perjuicio. En el caso no se acreditaron gastos ni el plazo de indisponibilidad. Muestra la prueba mínima que exigen algunas salas de PBA.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=185227', null, '2026-10-07'::date, 'relevamiento', 'e8a3137480fa8c73343e795e5f9b88e6'),
('fallo', 'Zampatti, Pablo Martín c/ Petroccelli, Jimena Yanina Z. y otros s/ Daños y Perjuicios (Sumario)', null, 'Cámara de Apelación en lo Civil y Comercial de Azul', 'II', '2018-05-22'::date, null, 'PBA', 'Civil y Comercial', null, null, array['privación de uso', 'daño emergente']::text[], 'a favor', 'La privación de uso genera siempre un daño emergente presumido (gastos de transporte) y un lucro cesante a probar; si el vehículo es utilitario, también el lucro cesante se presume y el juez puede fijarlo (art. 165 CPCC). Útil para taxis, fletes y vehículos de trabajo.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=161071', null, '2026-10-07'::date, 'relevamiento', '00199b197f7fb720b85001e0f87fc231'),
('fallo', 'De Jesus Vindeirinho, Héctor Marcelo c/ González, José Raúl s/ Daños y Perjuicios Extracontractual (Exc. Autom./Estado)', null, 'Cámara de Apelación en lo Civil y Comercial de Azul', 'II', '2019-10-31'::date, null, 'PBA', 'Civil y Comercial', null, null, array['privación de uso', 'daño emergente']::text[], 'mixto', 'Al cuantificar la privación de uso se descuentan los gastos que el actor se ahorró (combustible, seguro y mantenimiento mínimo), pero sin prueba específica de la demandada no se deducen gastos irregulares como estacionamiento. Ayuda a anticipar el descuento que pedirá la aseguradora.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=172392', null, '2026-10-07'::date, 'relevamiento', 'c8ea9cf2176f149c83ab98b9e12350c5'),
('fallo', 'Zaglio, Rosana Paola c/ Godoy, César Eraldo s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'I', '2025-08-19'::date, null, 'PBA', 'Civil y Comercial', null, null, array['incapacidad', 'concurrencia']::text[], 'mixto', 'Para la incapacidad del art. 1746 la sala usa la fórmula matemática de Acciarri, que contempla progreso de ingresos, jubilación, tasa de descuento y vida útil. En la mecánica, aclara que en cruces con semáforo no rige la prioridad de la derecha (art. 44 inc. c, Ley 24.449, Ley 13.927).', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=195177', null, '2026-10-07'::date, 'relevamiento', 'f6f9ba1a5dde32dbd38d003ac8a507c8'),
('fallo', 'Idoyaga, Patricia c/ Enriquez, Daniel s/ daños', null, 'Cámara de Apelación en lo Civil y Comercial de Mar del Plata', 'II', '2022-02-24'::date, null, 'PBA', 'Civil y Comercial', null, null, array['incapacidad']::text[], 'a favor', 'Critica oponer la "prudencia judicial" al uso de las matemáticas: el art. 1746 CCyC manda calcular un capital, de modo que el uso de fórmulas es exigencia legal. Argumento para pedir cuantificación con fórmula y no a valores discrecionales.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=183984', null, '2026-10-07'::date, 'relevamiento', 'af0b38c1ce972b22e3637469744b457a'),
('fallo', 'Evans, Facundo Nicolás y otro/a c/ Ortega, Diego Leonel s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'II', '2021-06-03'::date, null, 'PBA', 'Civil y Comercial', null, null, array['incapacidad']::text[], 'mixto', 'Postura opuesta: aplica un criterio elástico con las pautas del art. 1746, sin atarse a una fórmula financiera que prescinda de las circunstancias de la víctima, y exige que las lesiones sean permanentes. Conviene conocerla según la sala que toque.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=181250', null, '2026-10-07'::date, 'relevamiento', '126c3b2648dd11dcda2c6d2adfc8c079'),
('fallo', 'Rutigliano, Cristian Raúl y otro/a c/ La Biunda, Rocío Ailen s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'I', '2026-07-16'::date, null, 'PBA', 'Civil y Comercial', null, null, array['incapacidad', 'intereses']::text[], 'mixto', 'La incapacidad del art. 1746 abarca proyecciones no laborales con contenido económico (tareas domésticas, actividades cotidianas), aunque hay que probarlas. En intereses, aplica la doctrina SCBA de tasa pura del 6% sobre montos a valores actuales ("Vera", "Nidera", "Barrios") y descarta el 12% del juez de grado.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=198135', null, '2026-10-07'::date, 'relevamiento', '433f62003bd62461bd6e627fa0b62bed'),
('fallo', 'Bogado, Mirta y otro/a c/ Capdevielle Sánchez, Juan Ricardo y otro/a s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'I', '2026-07-14'::date, null, 'PBA', 'Civil y Comercial', null, null, array['concurrencia']::text[], 'mixto', 'La prioridad de la derecha del art. 41 de la Ley 24.449 es absoluta y solo se pierde en los supuestos que enumera; el exceso de velocidad no está entre ellos y, a lo sumo, incide en la causalidad. Ser embistente no pesa si el embestido se interpuso en la línea de marcha. Muy útil cuando el cliente venía por la derecha.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=198136', null, '2026-10-07'::date, 'relevamiento', '4e8361bc6c7283cfdec918cb2d14ce43'),
('fallo', 'Andrada, Octavio Mauro c/ Romero, Tomás y otros s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'I', '2026-03-12'::date, null, 'PBA', 'Civil y Comercial', null, null, array['concurrencia', 'intereses']::text[], 'mixto', 'La prioridad de quien viene por la derecha no se pierde porque no se pueda probar la mecánica, y no importa quién entró primero a la intersección (con cita de SCBA "Palamara"). En intereses, aplica tasa pura sobre montos a valores actuales desde el hecho.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=197125', null, '2026-10-07'::date, 'relevamiento', '415ab9f8da9abb68598d9765a587638f'),
('fallo', 'Guardia, Walter Martín y otros c/ Pérez, Guillermo David y otros s/ Daños y perjuicios', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2021-02-18'::date, null, 'PBA', 'Civil y Comercial', null, null, array['concurrencia']::text[], 'mixto', 'C. 123.002. La SCBA reitera que quien llega a la bocacalle debe ceder el paso al que viene por la derecha, sin importar quién llegó primero: la prioridad es absoluta y no depende de un arribo simultáneo. Doctrina legal de la Corte provincial; favorece a quien venía por la derecha.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=179412', null, '2026-10-07'::date, 'relevamiento', '9aad7aab0ad90cf0c5ab2ca39784ac25'),
('fallo', 'Ferreyra, Jorgelina María Inés y otro c/ Ministerio de Seguridad s/ Pretensión Indemnizatoria - Otros juicios - Recurso Extraordinario', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2026-03-06'::date, null, 'PBA', 'Contencioso administrativo', null, null, array['intereses']::text[], 'en contra', 'A. 77.911. Para créditos fijados a valores actuales, la SCBA aplica una tasa pura del 6% anual desde el daño hasta la cuantificación y, desde allí, la tasa pasiva más alta del Banco Provincia. Es la doctrina vigente en PBA, menos favorable que la tasa activa de Nación.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=196824', null, '2026-10-07'::date, 'relevamiento', 'cdfc5bfdfb1a8bf6f4b1374623791954'),
('fallo', 'Díaz, Alicia Susana c/ Moreno, Carlos s/ Daños y perjuicios', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2011-08-17'::date, null, 'PBA', 'Civil y Comercial', null, null, array['franquicia', 'citación en garantía']::text[], 'en contra', 'C. 102.992. La SCBA admite que la franquicia del contrato de seguro es oponible al tercero damnificado y que la condena contra la aseguradora solo se ejecuta dentro de lo contratado. Antecedente provincial alineado con la CSJN; anterior al CCyC.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=23930', null, '2026-10-07'::date, 'relevamiento', '50162ea12112d742709b32b368d53970'),
('fallo', 'Provincia Seguros S.A. s/ Materia a categorizar (incidente art. 250 inc. 2, CPCC) y C. 122.558, Provincia Seguros S.A. s/ Incidente', null, 'Suprema Corte de Justicia de la Provincia de Buenos Aires', null, '2021-05-28'::date, null, 'PBA', 'Civil y Comercial', null, null, array['citación en garantía']::text[], 'a favor', 'C. 122.557. Si al contestar la citación en garantía la aseguradora no planteó concretamente un límite derivado de la póliza, no puede introducirlo después al oponerse a los embargos: es extemporáneo y afecta la defensa. Útil contra planteos tardíos de límites de cobertura.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=180644', null, '2026-10-07'::date, 'relevamiento', 'b01d94521bb80840e304b5cf4a7a1a5a'),
('fallo', 'Valencia Huaracallo, Ana Laura y otros c/ Elías, Bernabé Jesús y otros s/ Daños y Perj. Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'I', '2025-09-30'::date, null, 'PBA', 'Civil y Comercial', null, null, array['citación en garantía', 'prescripción']::text[], 'mixto', 'Interlocutoria. Precisa la regla del art. 118 de que el asegurador no puede oponer defensas nacidas después del siniestro: distingue las internas del contrato (denuncia tardía, falta de pago de prima) de las externas a la relación asegurativa, como la prescripción de la acción. Sirve para contestar excepciones de la citada.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=195860', null, '2026-10-07'::date, 'relevamiento', 'e129e37f976f69b71776eb7eccbab2be'),
('fallo', 'Alfonso, José Clementino y otro/a c/ Río Uruguay Cooperativa de Seguros Limitada s/ Cumplimiento de contratos civiles/comerciales', null, 'Cámara de Apelación en lo Civil y Comercial de Mercedes', 'II', '2023-07-17'::date, null, 'PBA', 'Civil y Comercial', null, null, array['prescripción']::text[], 'a favor', 'En una relación de consumo con la aseguradora aplica el plazo genérico de cinco años del art. 2560 CCyC y desplaza el anual del art. 58 de la Ley de Seguros, con apoyo en el art. 1094 CCyC. Útil para reclamos del asegurado contra su compañía en PBA.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=188351', null, '2026-10-07'::date, 'relevamiento', '9b1a03c6226085b4de7d64aecd36b5f0'),
('fallo', 'Brizuela, Yanina Edith c/ Compañía de Seguros Mercantil Andina S.A. y otros s/ Daños y Perj. Autom. s/ Lesiones (Exc. Estado)', null, 'Cámara de Apelación en lo Civil y Comercial de Trenque Lauquen', null, '2023-05-24'::date, null, 'PBA', 'Civil y Comercial', null, null, array['prescripción']::text[], 'en contra', 'Aplica el art. 58 de la Ley de Seguros y rechaza el plazo de cinco años del CCyC, porque las normas generales de prescripción ceden ante la disposición específica (art. 2532 CCyC). Muestra que en PBA el criterio está dividido entre cámaras.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=187805', null, '2026-10-07'::date, 'relevamiento', '1075bdccc6f2b35df1b9027cf49e0f8f'),
('fallo', 'De la Canal Trofino, Roberto Emiliano c/ Rojas, Ricardo Daniel y otros s/ Ejecución de honorarios de mediación Ley 13.951', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'I', '2026-07-01'::date, null, 'PBA', 'Civil y Comercial', null, null, array['mediación']::text[], 'mixto', 'Explica que el mediador cobra una suma fija reglamentaria (art. 31, Ley 13.951) y el régimen del Decreto 600/2021 cuando, fracasada la mediación, el requirente no inicia el juicio en 90 días corridos. Clave para presupuestar el costo de la mediación en PBA.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=198482', null, '2026-10-07'::date, 'relevamiento', 'e6da17d4e97617fd370153a118a47bcd'),
('fallo', 'Quintana, Evangelina Eugenia c/ Guajardo, Adrián Gabriel y otros s/ Daños y Perjuicios Autom. c/ Les. o Muerte (Exc. Estado)', null, 'Cámara Primera de Apelación en lo Civil y Comercial de San Nicolás', null, '2025-02-20'::date, null, 'PBA', 'Civil y Comercial', null, null, array['mediación']::text[], 'mixto', 'El acuerdo alcanzado en la mediación prejudicial de PBA requiere homologación judicial para perfeccionarse; sin ella no produce efectos (arts. 19 a 22, Ley 13.951). Importante al cerrar acuerdos con aseguradoras en mediación.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=194655', null, '2026-10-07'::date, 'relevamiento', '9e46c09d3710f935a11650f9c28e0823'),
('fallo', 'De la Portilla, Héctor Daniel c/ Moabro, Carlos Eduardo y otros s/ Daños y Perj. Autom. s/ Lesiones (Exc. Estado)', null, 'Cámara Segunda de Apelación en lo Civil y Comercial de La Plata', 'II', '2022-11-01'::date, null, 'PBA', 'Civil y Comercial', null, null, array['mediación']::text[], 'mixto', 'Interlocutoria. Si el acta de cierre de la mediación no sirve como título para cobrar honorarios, se fijan los de la mediadora en forma provisoria y a cuenta de lo que resulte de la sentencia o la transacción (art. 31, Ley 13.951; Decreto 2530/10). Sirve para prever ese costo en el juicio.', false, 'https://juba.scba.gov.ar/VerTextoCompleto.aspx?idFallo=186133', null, '2026-10-07'::date, 'relevamiento', 'e4ccc010b1c8cd7e7655b6e1408b3281')
